<template>
<div class="rx">
 <header class="rx-head"><div><div class="rx-kicker">EINSTELLUNGEN / ONLINE-DIENSTE</div><h1>Verbindungen</h1><div class="rx-sub">KI-Anbieter, Modelle und Spotify verwalten.</div></div><span class="rx-chip" :class="{ok:bridgeFresh}">{{bridgeFresh?'Core erreichbar':'Core offline'}}</span></header>
 <div class="rx-grid">
  <section class="rx-panel rx-span-7">
   <div class="rx-panel-head"><h2>KI-Modell konfigurieren</h2><span class="rx-chip" :class="{ok:connectionSelectedHasKey}">{{connectionSelectedHasKey?'API-Key hinterlegt':'Kein API-Key'}}</span></div>
   <div class="rv-two">
    <div class="rx-field"><label>API-Anbieter</label><select class="rx-select" v-model="connectionProvider" @change="connectionUseProvider"><option v-for="provider in connectionProviders" :key="provider.id" :value="provider.id">{{provider.name}}</option></select></div>
    <div class="rx-field"><label>Modell auswählen</label><select class="rx-select" v-model="connectionModel"><option v-for="model in connectionModels" :key="model" :value="model">{{model}}</option><option value="">Modellliste laden und auswählen …</option></select></div>
   </div>
   <div class="rv-foot"><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||(!connectionSelectedHasKey &amp;&amp; !connectionKey)" @click="connectionLoadModels">{{connectionKey?'Key speichern & Modelle laden':'Modellliste laden'}}</button></div>
   <div class="rx-field"><label>API-Key für {{connectionProviderName}}</label><input class="rx-input" v-model="connectionKey" type="password" maxlength="512" autocomplete="new-password" placeholder="Neuen Schlüssel eingeben oder leer lassen" /><div class="rv-tip">Leer lassen behält den Key dieses Anbieters. Gespeicherte Keys werden nicht angezeigt.</div></div>
   <div style="display:grid;gap:10px;margin-top:16px">
    <label style="display:flex;gap:9px;align-items:flex-start"><input v-model="connectionConsent" type="checkbox" style="margin-top:4px" /><span>Freie Texte dürfen an {{connectionProviderName}} übermittelt werden. API-Kosten können entstehen.</span></label>
    <label style="display:flex;gap:9px;align-items:center"><input v-model="connectionEnabled" type="checkbox" /><span>Dieses Modell für Rovo aktivieren</span></label>
   </div>
   <div class="rv-foot"><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!connectionConsent||!connectionModel.trim()" @click="connectionSaveLLM">Modell &amp; Zugang speichern</button><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!connectionSelectionActive||!llmState.configured" @click="connectionSend('llm.test')">Gespeichertes Modell testen</button></div>
   <details style="margin-top:16px"><summary class="rx-small" style="cursor:pointer">Hinweise und Zugang entfernen</summary><p class="rv-tip">Lokale Befehle bleiben lokal. Kamera- und Personenprofile werden nicht übertragen; freie Texte können persönliche Angaben enthalten. Modelllisten können auch ungeeignete Modelle enthalten. Ein eingegebener Key wird nach erfolgreichem Laden der Modellliste gespeichert. Ein Modelltest kann API-Kosten verursachen.</p><label style="display:flex;gap:9px;align-items:center"><input v-model="connectionForgetLLM" type="checkbox" />Aktiven Anbieter samt Key entfernen bestätigen</label><div class="rv-foot"><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!connectionForgetLLM||!connectionSelectionActive" @click="connectionRemove('llm.forget')">Aktiven Zugang entfernen</button></div></details>
  </section>
  <section class="rx-panel rx-span-5">
   <div class="rx-panel-head"><h2>Aktive Verbindung</h2><span class="rx-chip">{{connectionProviderName}}</span></div>
   <div class="rv-model-summary"><div><span class="rx-label">Aktiver Anbieter</span><strong>{{llmState.provider||'—'}}</strong></div><div><span class="rx-label">Gespeichertes Modell</span><strong style="overflow-wrap:anywhere">{{llmState.model||'—'}}</strong></div></div>
   <div class="rx-row"><span>Text-KI</span><strong>{{llmState.enabled?'Aktiviert':'Deaktiviert'}}</strong></div><div class="rx-row"><span>Modelltest</span><strong>{{llmState.verified?'Erfolgreich':'Ungeprüft'}}</strong></div><div v-if="llmState.verified_at" class="rx-small">Letzte Prüfung: {{new Date(llmState.verified_at*1000).toLocaleString('de-DE')}}</div>
  </section>
  <section class="rx-panel rx-span-12">
   <div class="rx-panel-head"><h2>Spotify</h2><span class="rx-chip" :class="{ok:spotifyState.authorized}">{{spotifyState.authorized?'Angemeldet':'Nicht angemeldet'}}</span></div>
   <div class="rv-two"><div class="rx-field"><label>Spotify Client-ID</label><input class="rx-input" v-model="connectionClientId" maxlength="128" placeholder="Client-ID der Spotify-Developer-App" autocomplete="off" /></div><div class="rx-field"><label>Redirect-URI</label><input class="rx-input" v-model="connectionRedirect" maxlength="1000" autocomplete="off" /><div class="rv-tip">Exakt dieselbe Adresse in deiner Spotify-App hinterlegen.</div></div></div>
   <div class="rv-foot"><button class="rx-button" :disabled="!bridgeFresh||connectionBusy" @click="connectionSaveSpotify">App speichern</button><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!spotifyState.client_id" @click="connectionStartLogin">Mit Spotify verbinden</button><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!spotifyState.authorized" @click="connectionSend('spotify.devices')">Verbindung prüfen / Geräte laden</button></div>
   <div v-if="connectionAuthUrl" class="rv-warning" style="margin-top:16px"><strong>Spotify-Anmeldung abschließen</strong><p><a :href="connectionAuthUrl" target="_blank" rel="noopener noreferrer">Spotify-Anmeldung in neuem Tab öffnen</a></p><p class="rx-small">Danach die vollständige Rückleitungsadresse aus der Browserzeile hier einfügen. Auch bei „Seite nicht erreichbar“ enthält sie den Anmeldecode. Dieses Dashboard geöffnet lassen; der Link gilt zehn Minuten.</p><div class="rx-field"><label>Vollständige Rückleitungsadresse</label><input class="rx-input" v-model="connectionCallback" type="password" maxlength="4096" autocomplete="new-password" /></div><div class="rv-foot"><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!connectionCallback" @click="connectionComplete">Anmeldung abschließen</button><button class="rx-button" :disabled="!bridgeFresh" @click="connectionCancel">Abbrechen</button></div></div>
   <div class="rv-two" style="margin-top:16px"><div class="rx-field"><label>Spotify-Connect-Zielgerät</label><select class="rx-select" v-model="connectionDevice"><option value="">Gerät auswählen …</option><option v-if="connectionDevice &amp;&amp; !connectionDevices.some(d=>d.id===connectionDevice)" :value="connectionDevice">Gespeichertes Gerät: {{connectionDevice}}</option><option v-for="device in connectionDevices" :key="device.id" :value="device.id">{{device.name}} ({{device.type}})</option></select></div><div class="rx-field"><label>Geräteauswahl übernehmen</label><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!spotifyState.authorized||!connectionDevice" @click="connectionSend('spotify.select',{deviceId:connectionDevice})">Zielgerät speichern</button></div></div>
   <details style="margin-top:16px"><summary class="rx-small" style="cursor:pointer">Hinweise und Spotify trennen</summary><p class="rv-tip">Öffne Spotify auf dem Gerät, das Musik abspielen soll, und wähle es über „Geräte laden“ aus. Für Musik über die Lautsprecher am Pi muss dort zusätzlich ein Spotify-Abspielprogramm eingerichtet sein. Rovo übernimmt bisher nur die Steuerung. Die Anmeldung wird bei Bedarf automatisch verlängert; nach Ablauf oder Widerruf der Freigabe musst du dich erneut anmelden.</p><p class="rv-tip">„Spotify trennen“ löscht die gespeicherte Spotify-Einrichtung und Anmeldung auf Rovo. Danach musst du sie hier neu einrichten. Dein Spotify-Konto und dein Abo bleiben bestehen.</p><label style="display:flex;gap:9px;align-items:center"><input v-model="connectionForgetSpotify" type="checkbox" />Ja, Spotify-Einrichtung auf Rovo löschen</label><div class="rv-foot"><button class="rx-button" :disabled="!bridgeFresh||connectionBusy||!connectionForgetSpotify" @click="connectionRemove('spotify.disconnect')">Spotify trennen</button></div></details>
   <details v-if="runtimeState?.spotify?.configured" style="margin-top:16px"><summary class="rx-small" style="cursor:pointer">Musik ausprobieren</summary><div class="rx-field"><label>Titel oder Interpret</label><input class="rx-input" v-model="runtimeQuery" maxlength="120" placeholder="Titel oder Interpret" /></div><div class="rv-foot"><button class="rx-button" :disabled="!bridgeFresh" @click="runtimeSend('music.spotify',{query:runtimeQuery})">Abspielen</button><button class="rx-button" :disabled="!bridgeFresh" @click="runtimeSend('music.pause',{})">Pause</button><button class="rx-button" :disabled="!bridgeFresh" @click="runtimeSend('music.resume',{})">Fortsetzen</button><button class="rx-button" :disabled="!bridgeFresh" @click="runtimeSend('music.stop',{})">Stoppen</button></div></details>
  </section>
  <section class="rx-panel rx-span-12"><div class="rx-panel-head"><h2>Verbindungsstatus</h2><span class="rx-chip" :class="{warn:connectionBusy}">{{connectionBusy?'Anfrage läuft':'Bereit'}}</span></div><div class="rv-status" role="status">{{connectionNotice}}</div><p v-if="runtimeState?.connections?.error" class="rv-warning" role="alert">{{runtimeState.connections.error}}</p></section>
 </div>
</div>
</template>
<script>
export default {
 data(){return {connectionNotice:'Core-Status wird geladen.',connectionBusy:false,connectionTimer:null,connectionLoaded:false,llmState:{},spotifyState:{},connectionProvider:'openai',connectionProviders:[{id:'openai',name:'OpenAI'},{id:'anthropic',name:'Anthropic · Claude'},{id:'google',name:'Google · Gemini'},{id:'openrouter',name:'OpenRouter'},{id:'mistral',name:'Mistral AI'},{id:'groq',name:'Groq'}],connectionProfiles:{},connectionCatalog:{},connectionModel:'',connectionKey:'',connectionConsent:false,connectionEnabled:false,connectionForgetLLM:false,connectionClientId:'',connectionRedirect:'http://127.0.0.1:8888/callback',connectionAuthUrl:'',connectionCallback:'',connectionDevice:'',connectionDevices:[],connectionForgetSpotify:false}},
 computed:{
  connectionProviderName(){return this.connectionProviders.find(p=>p.id===this.connectionProvider)?.name||this.connectionProvider},
  connectionSelectedHasKey(){return !!this.connectionProfiles[this.connectionProvider]?.has_key},
  connectionSelectionActive(){return this.llmState.provider===this.connectionProvider && this.llmState.model===this.connectionModel.trim()},
  connectionModels(){const p=this.connectionProfiles[this.connectionProvider]||{};return [...new Set([...(p.model?[p.model]:[]),...(this.connectionCatalog[this.connectionProvider]||[])])].sort()}
 },
 methods:{
  connectionUseProvider(){this.connectionKey='';this.connectionConsent=false;this.connectionForgetLLM=false;const p=this.connectionProfiles[this.connectionProvider]||{};this.connectionModel=p.model||'';this.connectionEnabled=this.llmState.provider===this.connectionProvider && this.llmState.enabled===true},
  connectionSend(action,data={}){if(!this.bridgeFresh||(this.connectionBusy && action!=='spotify.cancel'))return;this.connectionBusy=true;this.connectionNotice='Anfrage läuft …';this.send({payload:{action,data}});clearTimeout(this.connectionTimer);this.connectionTimer=setTimeout(()=>{this.connectionBusy=false;this.connectionNotice='Antwort ausgeblieben. Status prüfen; keine automatische Wiederholung.'},35000)},
  connectionLoadModels(){const apiKey=this.connectionKey;this.connectionKey='';this.connectionSend('llm.models',{provider:this.connectionProvider,apiKey})},
  connectionSaveLLM(){const apiKey=this.connectionKey;this.connectionKey='';this.connectionSend('llm.save',{provider:this.connectionProvider,model:this.connectionModel.trim(),apiKey,allowCloud:this.connectionConsent,enabled:this.connectionEnabled})},
  connectionSaveSpotify(){this.connectionAuthUrl='';this.connectionCallback='';this.connectionSend('spotify.save',{clientId:this.connectionClientId,redirectUri:this.connectionRedirect})},
  connectionStartLogin(){this.connectionAuthUrl='';this.connectionSend('spotify.login')},
  connectionComplete(){const callbackUrl=this.connectionCallback;this.connectionCallback='';this.connectionSend('spotify.complete',{callbackUrl})},
  connectionCancel(){this.connectionAuthUrl='';this.connectionCallback='';this.connectionSend('spotify.cancel')},
  connectionRemove(action){this.connectionAuthUrl='';this.connectionCallback='';this.connectionSend(action,{confirm:action==='llm.forget'?this.connectionForgetLLM:this.connectionForgetSpotify});this.connectionForgetLLM=false;this.connectionForgetSpotify=false},
  connectionStatus(llm,spotify){if(llm){this.llmState=llm;this.connectionProfiles=llm.profiles||{};if(llm.providers?.length)this.connectionProviders=llm.providers}if(spotify)this.spotifyState=spotify;if(!this.connectionLoaded){this.connectionProvider=llm?.provider||'openai';this.connectionModel=llm?.model||'';this.connectionEnabled=llm?.enabled===true;this.connectionClientId=spotify?.client_id||'';this.connectionRedirect=spotify?.redirect_uri||this.connectionRedirect;this.connectionDevice=spotify?.device_id||'';this.connectionLoaded=true}}
 },
 watch:{msg:{immediate:true,handler(m){const p=m?.payload;if(p?.kind==='snapshot' && p.runtime)this.connectionStatus(p.runtime.llm,p.runtime.spotify);if(p?.kind==='integrations' && p.action!=='status'){clearTimeout(this.connectionTimer);this.connectionBusy=false;this.connectionNotice=p.message||'Antwort empfangen.';this.connectionStatus(p.status?.llm,p.status?.spotify);if(p.ok && p.data?.auth_url && p.data.auth_url.startsWith('https://accounts.spotify.com/authorize?'))this.connectionAuthUrl=p.data.auth_url;if(p.ok && p.data?.devices)this.connectionDevices=p.data.devices;if(p.ok && p.action==='llm.models' && p.data?.provider)this.connectionCatalog={...this.connectionCatalog,[p.data.provider]:p.data.models||[]};if(p.ok && ['spotify.complete','spotify.disconnect','spotify.cancel'].includes(p.action))this.connectionAuthUrl='';if(p.ok && p.action==='llm.forget'){this.connectionKey='';this.connectionEnabled=false;this.connectionConsent=false}}else if(p?.kind==='ack' && p.ok===false){clearTimeout(this.connectionTimer);this.connectionBusy=false;this.connectionNotice=p.message||'Anfrage fehlgeschlagen.'}}}},
 mounted(){this.send({payload:{action:'ui.sync',data:{}}})},
 unmounted(){clearTimeout(this.connectionTimer);this.connectionKey='';this.connectionCallback='';this.connectionAuthUrl=''}
}
</script>
